Set Variable [ $r ; Value: MBSAttachment(EmailID, FilePathList, Flag_inline)

// e.g. $r=MBSattachment ( $EmailID ; MyTable::FilePathList; 1 ) ;

Case(
ValueCount (FilePathList ) > 0;
	Let(
	[
		§element = 
			ValueCount (FilePathList ) ;
		§Line = 
			GetValue( FilePathList; §element );
		§InlineID= 
			MBS( "Path.LastPathComponent"; §line ) ;
		§r= 
			MBS( 
			"SendMail.AddAttachmentFile"; 
			EmailID;
			§Line;
			""; /* file name from path automatically */
			""; /* mime name from file name automatically */
			Case(
				Flag_inline = 1;
					§InlineID ;
				""
				)
			)
	];

	// call recursive for next file:
	MBSattachment(
		EmailID; 		
		Trim(
		Substitute( 
			"¶" & FilePathList; 
			"¶" & §Line ; 
			"" 
		)); 
		Flag_inline
	)
);
	""
) ]

Set Variable [ $r ; Value: Let([
t = MBS( "Time.Format"; Get ( CurrentTimeStamp ); "%a, %d %b %Y %H:%M:%S %z");
l = Length ( t );
w = Position ( t ; ":" ; 1 ; 3 );
r = if(w > 0; t; Left ( t ; l-2 ) & ":" & Middle ( t ; l-2 ; 2 ))
]; t & ¶ & r) ]

